        line_total(item["qty"], item["unit_price"])
        for item in items
        if not item.get("tax_exempt", False)
    )
    exempt = sum(
        line_total(item["qty"], item["unit_price"])
        for item in items
        if item.get("tax_exempt", False)
    )
    return round(taxable * (1 + tax_rate) + exempt, 2)
