import csv
from collections import defaultdict
from os import PathLike


def load_rows(path: str | PathLike[str]) -> list[dict[str, str]]:
    """Read invoice rows from a CSV file."""
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def totals_by_customer(rows: list[dict[str, str]]) -> dict[str, float]:
    """Total billed amount per customer."""
    totals: defaultdict[str, float] = defaultdict(float)
    for row in rows:
        totals[row["customer"]] += float(row["amount"])
    # TODO: use Decimal instead of float for money
    return dict(totals)
